  var nativeTransfer = async (amount, destinationAddress, provider, signer, signingKey) => {
    return await provider.api.tx.balances.transfer(destinationAddress, amount).signAndSend(signer.address, { signer: signingKey });
  };
  var nativeTransfer$ = (amount, destinationAddress, provider, signer, signingKey) => {
    return new Observable((observer) => {
      const unsub = provider.api.tx.balances.transfer(destinationAddress, amount).signAndSend(signer.address, { signer: signingKey }, (result) => {
        if (result.status.isBroadcast) {
          observer.next({ status: "broadcast" });
        } else if (result.status.isInBlock) {
          observer.next({ status: "included-in-block", blockHash: result.status.asInBlock.toString() });
        } else if (result.status.isFinalized) {
          observer.next({ status: "finalized", blockHash: result.status.asFinalized.toString() });
          setTimeout(() => {
            observer.complete();
          });
        }
      }).catch((err) => {
        observer.error(err);
      });
    });
  };
  var getSignerEvmAddress = async (address, provider) => {
    if (address.length !== 48 || address[0] !== "5") {
      return address;
    }
    const evmAddress = await provider.api.query.evmAccounts.evmAddresses(address);
    const addr = evmAddress.toString();
    if (!addr) {
      throw new Error("EVM address does not exist");
    }
    return addr;
  };
  function reef20Transfer$(to2, provider, tokenAmount, tokenContract) {
    const STORAGE_LIMIT = 2e3;
    return new Observable((observer) => {
      (async () => {
        const toAddress2 = to2.length === 48 ? await getSignerEvmAddress(to2, provider) : to2;
        const ARGS = [toAddress2, tokenAmount];
        tokenContract["transfer"](...ARGS, {
          customData: {
            storageLimit: STORAGE_LIMIT
          }
        }).then((tx2) => {
          observer.next({ status: "broadcast", transactionResponse: tx2 });
          console.log("tx in progress =", tx2.hash);
          tx2.wait().then(async (receipt) => {
            console.log("transfer included in block=", receipt.blockHash);
            observer.next({ status: "included-in-block", transactionReceipt: receipt });
            let count = 10;
            const finalizedCount = -111;
            const unsubHeads = await provider.api.rpc.chain.subscribeFinalizedHeads((lastHeader) => {
              if (receipt.blockHash.toString() === lastHeader.hash.toString()) {
                observer.next({ status: "finalized", transactionReceipt: receipt });
                count = finalizedCount;
              }
              if (--count < 0) {
                if (count > finalizedCount) {
                  observer.next({ status: "not-finalized", transactionReceipt: receipt });
                }
                unsubHeads();
                observer.complete();
              }
            });
          }).catch((err) => {
            console.log("transfer tx.wait ERROR=", err.message);
            observer.error(err);
          });
        }).catch((err) => {
          console.log("transfer ERROR=", err.message);
          observer.error(err);
        });
      })();
    });
  }
